#include <iostream>
#include <cstdio>
using namespace std;

int countDigits(long long n) {
    int digits = 0;
    while (n > 0) {
        n /= 10;
        digits++;
    }
    return digits;
}

long long getLargestOnes(long long n) {
    int length = countDigits(n);
    long long sum = 0, power = 1;
    for (int i = 0; i < length; i++) {
        sum += power;
        power *= 10;
    }
    if (sum <= n) return sum;
    return (sum - 1) / 10;
}

long long solve(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base = getLargestOnes(n);
    long long nextVal = base * 10 + 1;
    if (n % base == 0) {
        if (n <= (nextVal / 2 + base))
            return countDigits(base) * n / base;
        return countDigits(nextVal) + solve(nextVal - n);
    } else {
        long long m = (n / base) * base;
        long long result = solve(m) + solve(n - m);
        if (n > nextVal / 2)
            result = min(solve(m) + solve(n - m), countDigits(nextVal) + solve(nextVal - n));
        return result;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << solve(n) << endl;
    return 0;
