    next_val = base * 10 + 1
    if n % base == 0:
        if n <= (next_val // 2 + base):
            return count_digits(base) * n // base
        return count_digits(next_val) + solve(next_val - n)
    else:
        m = (n // base) * base
        result = solve(m) + solve(n - m)
        if n > next_val // 2:
            result = min(solve(m) + solve(n - m), count_digits(next_val) + solve(next_val - n))
